  "summary": "The code contains a critical SQL injection vulnerability, lacks proper dependency management, and uses hardcoded configurations. Overall code health is poor due to tight coupling and lack of input validation. The refactored code introduces parameterized queries, environment variable support, and basic input validation.",
  "fixed_code": "const express = require('express');\nconst app = express();\nconst db = require('./db'); // Assuming db client is exported from a module\n\n/**\n * @param {import('express').Request} req\n * @param {import('express').Response} res\n */\nconst getUser = async (req, res) => {\n    const { username } = req.query;\n    if (!username || typeof username !== 'string') {\n        return res.status(400).send('Invalid username');\n    }\n\n    const query = 'SELECT * FROM users WHERE username = ? LIMIT 1';\n    db.query(query, [username], (err, results) => {\n        if (err) {\n            return res.status(500).send('Database error');\n        }\n        res.json(results);\n    });\n};\n\napp.get('/user', getUser);\n\nconst PORT = process.env.PORT || 3000;\napp.listen(PORT, () => console.log(`Server running on port ${PORT}`));"
